import java.io.*;

public class Task {

    static final int MOD = 1000000007;

    static BufferedInputStream bin;
    static PrintWriter out;

    public static void main(String[] args) throws Exception {
        try {
            bin = new BufferedInputStream(new FileInputStream("input.txt"));
            out = new PrintWriter(new BufferedWriter(new FileWriter("output.txt")));
        } catch (Exception e) {
            bin = new BufferedInputStream(System.in);
            out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
        }

        int n = nextInt();
        int total = 2 * n;
        int[][] dp = new int[total][n + 1];
        dp[0][1] = 1;

        for (int i = 1; i < total; i++) {
            int[] prev = dp[i - 1];
            int[] cur = dp[i];
            for (int j = 0; j <= n; j++) {
                int v = prev[j];
                if (j + 1 <= n) {
                    cur[j + 1] = (cur[j + 1] + v) % MOD;
                }
                if (j - 1 >= 0) {
                    cur[j - 1] = (cur[j - 1] + v) % MOD;
                }
            }
        }

        int ans = 0;
        for (int i = total - 2; i >= 0; i -= 2) {
            int limit = total - 1 - i;
            for (int j = 1; j <= n; j += 2) {
                if (j <= limit) {
                    ans = (ans + dp[i][j]) % MOD;
                }
            }
        }

        out.print(ans);
        out.flush();
        out.close();
    }

    static int nextInt() throws IOException {
        int c;
        do {
            c = bin.read();
        } while (c != -1 && c <= ' ');

        int sign = 1;
        if (c == '-' || c == '+') {
            if (c == '-') {
                sign = -1;
            }
            c = bin.read();
        }

        int value = 0;
        while (c != -1 && c > ' ') {
            value = value * 10 + (c - '0');
            c = bin.read();
        }
        return sign * value;
    }
}
